/**
 * Order Service — Order creation, cancellation (2-hr window), and lifecycle management.
 * Generated by BackendForge
 */
const { env } = require('../config/env');
const { ApiError } = require('../middleware/error-handler.middleware');
const { logAuditAction } = require('../middleware/audit-log.middleware');
const { Order, OrderItem, Cart, Product, User, Address } = require('../models');
const { sequelize } = require('../config/database');

const orderService = {
  /**
   * Create a new order from the user's cart.
   */
  async createOrder(userId, orderData) {
    const { shippingAddressId, paymentMethod, customerNotes } = orderData;

    // Get user's cart
    const cart = await Cart.findOne({ where: { userId } });

    if (!cart || !cart.items || cart.items.length === 0) {
      throw ApiError.badRequest('Cart is empty', 'EMPTY_CART');
    }

    // Get shipping address
    const address = await Address.findOne({ where: { id: shippingAddressId, userId } });
    if (!address) throw ApiError.badRequest('Invalid shipping address', 'INVALID_ADDRESS');

    // Validate stock and calculate totals
    let subtotal = 0;
    const orderItems = [];

    for (const item of cart.items) {
      const product = await Product.findByPk(typeof item === 'object' ? item.productId : item.productId);

      if (!product || !product.isActive) {
        throw ApiError.badRequest(`Product "${item.name || 'unknown'}" is no longer available`, 'PRODUCT_UNAVAILABLE');
      }
      if (product.stock < (item.quantity || 1)) {
        throw ApiError.badRequest(`Insufficient stock for "${product.name}". Available: ${product.stock}`, 'INSUFFICIENT_STOCK');
      }

      const qty = item.quantity || 1;
      const price = parseFloat(product.price);
      subtotal += price * qty;

      orderItems.push({
        productId: product.id,
        name: product.name,
        price,
        quantity: qty,
        image: product.images?.[0]?.url || null,
      });

      // Reduce stock
      product.stock -= qty;
      await product.save();
    }

    const tax = subtotal * 0.18; // 18% GST
    const shippingCost = subtotal > 999 ? 0 : 99; // Free shipping over ₹999
    const totalAmount = subtotal + tax + shippingCost;

    // Create order
    const order = await sequelize.transaction(async (t) => {
      const newOrder = await Order.create({
        userId,
        subtotal,
        tax: Math.round(tax * 100) / 100,
        shippingCost,
        totalAmount: Math.round(totalAmount * 100) / 100,
        paymentMethod,
        customerNotes,
        shippingStreet: address.street,
        shippingCity: address.city,
        shippingState: address.state,
        shippingZipCode: address.zipCode,
        shippingCountry: address.country,
        paymentStatus: 'pending',
        shippingStatus: 'pending',
      }, { transaction: t });

      // Create order items
      await OrderItem.bulkCreate(
        orderItems.map(item => ({ ...item, orderId: newOrder.id })),
        { transaction: t }
      );

      return newOrder;
    });

    // Clear cart after successful order
    await Cart.update({ items: [], totalAmount: 0 }, { where: { userId } });

    return order;
  },

  /**
   * Get order by ID. Customers can only see their own orders.
   */
  async getOrderById(orderId, userId, userRole) {
    const query = { where: { id: orderId }, include: [
      { model: OrderItem, as: 'items' },
      { model: User, as: 'user', attributes: ['id', 'name', 'email', 'phone'] },
    ]};
    if (!['admin', 'superadmin'].includes(userRole)) {
      query.where.userId = userId;
    }
    const order = await Order.findOne(query);
    if (!order) throw ApiError.notFound('Order not found', 'ORDER_NOT_FOUND');
    return order;
  },

  /**
   * Cancel order — enforces 2-hour cancellation window.
   */
  async cancelOrder(orderId, userId, reason) {
    const order = await Order.findOne({ where: { id: orderId, userId } });

    if (!order) throw ApiError.notFound('Order not found', 'ORDER_NOT_FOUND');
    if (order.isCancelled) throw ApiError.badRequest('Order is already cancelled', 'ALREADY_CANCELLED');
    if (order.shippingStatus === 'delivered') {
      throw ApiError.badRequest('Delivered orders cannot be cancelled', 'CANNOT_CANCEL_DELIVERED');
    }

    // Enforce 2-hour cancellation window
    const cancelWindowHours = parseInt(env.ORDER_CANCEL_WINDOW_HOURS) || 2;
    const orderAge = (Date.now() - new Date(order.createdAt).getTime()) / (1000 * 60 * 60);
    if (orderAge > cancelWindowHours) {
      throw ApiError.badRequest(
        `Orders can only be cancelled within ${cancelWindowHours} hours of placement. This order was placed ${Math.round(orderAge)} hours ago.`,
        'CANCEL_WINDOW_EXPIRED'
      );
    }

    // Cancel the order
    await order.update({
      isCancelled: true,
      cancelledAt: new Date(),
      cancelReason: reason,
      cancelledBy: 'customer',
      shippingStatus: 'returned',
    });

    // Restore product stock
    const items = await OrderItem.findAll({ where: { orderId: order.id } });
    for (const item of items) {
      await Product.increment('stock', { by: item.quantity, where: { id: item.productId } });
    }

    return order;
  },
};

module.exports = orderService;
